<?php
// Общий блок «Сервер без оболочки (консоль)» для страниц Debian и Ubuntu (русский и английский). Правится в одном месте.
function yandi_cli_guide(string $lang): void {
    $ru = $lang === 'ru';
    $unit = "systemctl status yandi-node@\$USER\njournalctl -u yandi-node@\$USER -f\n\n# ".($ru ? 'если служба не включилась сама (например, пакет ставили не через sudo):' : 'if the service was not enabled automatically (for example, the package was not installed through sudo):')."\nsudo systemctl enable --now yandi-node@\$USER";
    $t = $ru ? [
        'h' => 'Сервер без оболочки (только консоль)',
        'lead' => 'Оболочка (окно) не обязательна: узел полностью настраивается и управляется из терминала. Так обычно ставят узел на сервер.',
        's1' => 'Установка только узла', 'p1' => 'Скачайте только <code>yandi-node_*.deb</code> (пакет оболочки <code>yandi-desktop</code> нужен лишь для окна управления) и установите:',
        's2' => 'Первая настройка', 'p2' => 'Запускайте от обычного пользователя (не от root): данные узла лежат в его домашней папке. Мастер спросит язык, длину сид-фразы (по умолчанию 24 слова; можно 12 или 18), задаст пароль владельца, покажет сид-фразу, предложит необязательное контрольное слово, создаст закрытую среду и спросит, где хранить копии связей:',
        'w2' => '<strong>Запишите сид-фразу на бумагу и проверьте.</strong> Она показывается один раз и нужна для восстановления; без неё и пароля данные не вернуть. Без терминала: <code>yandi setup --seed-file seed.txt --password-stdin</code> (фраза пишется в новый файл с правами 0600).',
        's2b' => 'Копии связей и восстановление', 'p2b' => 'Копии (сопряжённые телефоны, контакты, группы) пишутся в выбранное место, в папку <code>yandi-node</code>; узел сам проверяет запись и предупреждает, если место на системном диске. Хранится 7 автокопий; копия делается при изменениях в течение 10 минут. Позже: <code>yandi admin backup status | set-dir ПУТЬ | now</code>. Восстановление на новой машине: <code>yandi setup --restore</code> (сид-фраза, контрольное слово, номер узла для сверки, по желанию файл <code>.yandibak</code> или папка <code>yandi-node</code>); проверить фразу и слово, ничего не меняя: <code>yandi setup --check</code>.',
        's3' => 'Служба и порты', 'p3' => 'Пакет сам включает и запускает службу systemd <code>yandi-node@ВАШ_ПОЛЬЗОВАТЕЛЬ</code> для пользователя, который ставил пакет через <code>sudo</code>: узел работает в фоне и поднимается после перезагрузки. До <code>yandi setup</code> он просто ждёт первой настройки. Проверить:',
        'p3b' => 'Откройте порты (пример для <code>ufw</code>; для <code>nftables</code> см. <code>/usr/share/doc/yandi-node/DEPLOYMENT.md</code>): 8444/TCP — вход для приложения на телефоне; 9000/UDP и 10000/UDP — сеть узлов. Рекомендуем также расширить сетевые буферы (иначе под нагрузкой ядро теряет UDP-пакеты; при старте узел предупреждает, если буфер приёма меньше 4 МБ): по 64 МБ на приём и отправку и более длинную очередь пакетов от сетевой карты. Последняя команда покажет действующие значения: 67108864, 67108864 и 5000.',
        'n3' => 'По желанию: кольцевой буфер самой сетевой карты задаётся командами <code>ethtool -g</code> (показать) и <code>ethtool -G eth0 rx 4096 tx 4096</code> (в пределах, которые сообщает карта); у многих карт, например Realtek <code>r8169</code>, его менять нельзя.',
        's4' => 'Управление из консоли', 'p4' => 'Команда <code>yandi admin</code> спрашивает пароль администратора (сеанс 15 минут). Без аргументов открывает меню; основные команды:',
        'c4' => ['yandi admin status' => 'состояние узла', 'yandi admin devices' => 'устройства и пользователи', 'yandi admin pairing owner --host ВАШ_АДРЕС' => 'код и QR для сопряжения телефона', 'yandi admin invites show' => 'политика приглашений', 'yandi admin device-promote ID' => 'подтвердить приглашённого пользователя', 'yandi admin device-remove ID' => 'отвязать устройство', 'yandi admin vault status' => 'закрытая среда: замок, смена пароля', 'yandi admin bootstrap applications' => 'заявки новых узлов (для владельца списка входных узлов)'],
        's5' => 'Подключение телефона', 'p5' => 'Выполните <code>yandi admin pairing owner --host ВАШ_ВНЕШНИЙ_АДРЕС</code>: узел покажет код сопряжения и QR. В приложении YANDI на первом экране наведите камеру на QR или вставьте текст кода (он начинается с <code>YANDI-PAIR-1:</code>). Код одноразовый.',
        's6' => 'Язык', 'p6' => 'Язык консоли: ключ <code>--lang ru|en</code>, переменная <code>YANDI_LANG=en</code> или сохранённый выбор (<code>~/.config/yandi/lang</code>). Без выбора берётся язык системы.',
        's7' => 'Журнал, обновление, удаление',
        'l7' => ['Журнал службы: <code>journalctl -u yandi-node -f</code>.', 'Обновление: установите новый пакет поверх старого (<code>sudo apt install ./yandi-node_*.deb</code>), затем <code>sudo systemctl restart yandi-node</code>. Данные сохраняются.', 'Удаление программы с сохранением данных: <code>sudo apt remove yandi-node</code>. Полное удаление вместе с данными (затирает и удаляет без следа): <code>sudo apt purge yandi-node</code>; перед этим убедитесь, что сид-фраза записана.'],
    ] : [
        'h' => 'Server without the shell (console only)',
        'lead' => 'The shell (the window) is optional: the node can be fully set up and managed from a terminal. This is how a node is usually installed on a server.',
        's1' => 'Install the node only', 'p1' => 'Download only <code>yandi-node_*.deb</code> (the <code>yandi-desktop</code> package is needed just for the management window) and install it:',
        's2' => 'First setup', 'p2' => 'Run it as a regular user (not root): the node data lives in that user\'s home directory. The wizard asks for the language and the seed phrase length (24 words by default; 12 or 18 are possible), sets the owner password, shows the seed phrase, offers an optional control word, creates the private environment and asks where to keep backups of the links:',
        'w2' => '<strong>Write the seed phrase on paper and check it.</strong> It is shown once; with it (and the control word, if you set one) the node is fully restored on any machine: the same identity, the same trust. The <strong>control word</strong> is one word (8–64 characters, case matters) that you invent and keep apart from the seed phrase; without it the seed will not restore the node, and if you forget it the node cannot be brought back. The node number for checking at restore is shown at setup. Without a terminal: <code>yandi setup --seed-file seed.txt --password-stdin --backup-dir /media/user/FLASH --yes</code> (the phrase goes to a new file with mode 0600).',
        's2b' => 'Backups of the links and restore', 'p2b' => 'Backups (paired phones, contacts, groups) are written to the chosen place, into a <code>yandi-node</code> folder; the node checks the write itself and warns if the place is on the system disk. 7 automatic backups are kept; a backup is made within 10 minutes of a change. Later: <code>yandi admin backup status | set-dir PATH | now</code>. Restore on a new machine: <code>yandi setup --restore</code> (seed phrase, control word, the node number to compare, optionally a <code>.yandibak</code> file or the <code>yandi-node</code> folder); check a phrase and word without changing anything: <code>yandi setup --check</code>.',
        's3' => 'Service and ports', 'p3' => 'The package itself enables and starts the systemd service <code>yandi-node@YOUR_USER</code> for the user who installed it through <code>sudo</code>: the node runs in the background and comes up after a reboot. Until <code>yandi setup</code> it just waits for the first setup. Check:',
        'p3b' => 'Open the ports (an example for <code>ufw</code>; for <code>nftables</code> see <code>/usr/share/doc/yandi-node/DEPLOYMENT.md</code>): 8444/TCP — entrance for the phone app; 9000/UDP and 10000/UDP — the node network. We also recommend bigger network buffers (otherwise the kernel drops UDP packets under load; the node warns at start if the receive buffer is under 4 MB): 64 MB for receiving and sending and a longer queue of packets from the network card. The last command shows the values in effect: 67108864, 67108864 and 5000.',
        'n3' => 'Optional: the ring buffer of the network card itself is set with <code>ethtool -g</code> (show) and <code>ethtool -G eth0 rx 4096 tx 4096</code> (set, within the limits the card reports); many cards, for example Realtek <code>r8169</code>, do not allow changing it.',
        's4' => 'Managing from the console', 'p4' => '<code>yandi admin</code> asks for the administrator password (a 15-minute session). Without arguments it opens a menu; the main commands:',
        'c4' => ['yandi admin status' => 'node status', 'yandi admin devices' => 'devices and users', 'yandi admin pairing owner --host YOUR_ADDRESS' => 'code and QR to pair a phone', 'yandi admin invites show' => 'invitation policy', 'yandi admin device-promote ID' => 'confirm an invited user', 'yandi admin device-remove ID' => 'unpair a device', 'yandi admin vault status' => 'private environment: lock, change password', 'yandi admin bootstrap applications' => 'applications from new nodes (for the owner of the entry-node list)'],
        's5' => 'Connecting a phone', 'p5' => 'Run <code>yandi admin pairing owner --host YOUR_PUBLIC_ADDRESS</code>: the node prints a pairing code and a QR. On the first screen of the YANDI app point the camera at the QR or paste the code text (it starts with <code>YANDI-PAIR-1:</code>). The code is single-use.',
        's6' => 'Language', 'p6' => 'Console language: the <code>--lang ru|en</code> option, the <code>YANDI_LANG=en</code> variable or the saved choice (<code>~/.config/yandi/lang</code>). Without a choice the system language is used.',
        's7' => 'Log, updating, removal',
        'l7' => ['Service log: <code>journalctl -u yandi-node -f</code>.', 'Updating: install the new package over the old one (<code>sudo apt install ./yandi-node_*.deb</code>), then <code>sudo systemctl restart yandi-node</code>. The data is kept.', 'Removing the program but keeping the data: <code>sudo apt remove yandi-node</code>. Complete removal together with the data (wiped without a trace): <code>sudo apt purge yandi-node</code>; make sure the seed phrase is written down first.'],
    ];
    $sysctl = "sudo ufw allow 8444/tcp\nsudo ufw allow 9000/udp\nsudo ufw allow 10000/udp\n\nprintf 'net.core.rmem_max=67108864\\nnet.core.wmem_max=67108864\\nnet.core.netdev_max_backlog=5000\\n' | sudo tee /etc/sysctl.d/99-yandi.conf\nsudo sysctl --system\n\n# проверка / check\ncat /proc/sys/net/core/rmem_max /proc/sys/net/core/wmem_max /proc/sys/net/core/netdev_max_backlog";
    ?>
    <div class="download-steps"><h3><?= $t['h'] ?></h3><p><?= $t['lead'] ?></p>
    <h4>1. <?= $t['s1'] ?></h4><p><?= $t['p1'] ?></p><pre>sudo apt install ./yandi-node_*.deb</pre>
    <h4>2. <?= $t['s2'] ?></h4><p><?= $t['p2'] ?></p><pre>yandi setup</pre><p><?= $t['w2'] ?></p>
    <h4>3. <?= $t['s2b'] ?></h4><p><?= $t['p2b'] ?></p>
    <h4>4. <?= $t['s3'] ?></h4><p><?= $t['p3'] ?></p><pre><?= htmlspecialchars($unit, ENT_QUOTES) ?></pre><p><?= $t['p3b'] ?></p><pre><?= htmlspecialchars($sysctl, ENT_QUOTES) ?></pre><p><?= $t['n3'] ?></p>
    <h4>5. <?= $t['s4'] ?></h4><p><?= $t['p4'] ?></p><ul><?php foreach ($t['c4'] as $cmd => $what): ?><li><code><?= htmlspecialchars($cmd, ENT_QUOTES) ?></code> — <?= $what ?></li><?php endforeach; ?></ul>
    <h4>6. <?= $t['s5'] ?></h4><p><?= $t['p5'] ?></p>
    <h4>7. <?= $t['s6'] ?></h4><p><?= $t['p6'] ?></p>
    <h4>8. <?= $t['s7'] ?></h4><ul><?php foreach ($t['l7'] as $l): ?><li><?= $l ?></li><?php endforeach; ?></ul></div>
    <?php
}
